"""Compare authored runtime variants without repeating a course five times."""
import json
from pathlib import Path
root=Path(__file__).resolve().parents[1]
pack=json.loads((root/'assets/levels/endless/pack.json').read_text())
page='''<!doctype html><meta charset="utf-8"><title>Mektra · Route variations</title><style>body{margin:0;background:#10141e;color:#f5f7ff;font:16px system-ui}header{padding:24px 32px;position:sticky;top:0;background:#10141ef2;z-index:1}h1{font-size:24px;margin:0 0 8px}p{color:#b8c2d6;line-height:1.5}select{background:#263046;color:white;padding:12px;border:1px solid #48566e;border-radius:10px;font:inherit;width:min(100%,500px)}main{display:grid;grid-template-columns:repeat(4,minmax(160px,1fr));gap:20px;padding:12px 32px 32px;max-width:1300px;margin:auto}.card{background:#202939;padding:16px;border-radius:16px}.card h2{font-size:16px}.card svg{width:100%;background:#9ca3af;border-radius:10px}.card p{font-size:13px} @media(max-width:700px){main{grid-template-columns:repeat(2,1fr);padding:12px}}</style><header><h1>Mektra · Different journeys within each world</h1><p>Four playable variants. Each view shows one actual 390 × 1080 course, so the route differences are easy to compare.</p><select id="world"></select></header><main id="cards"></main><script>
const pack=PACK;const select=document.querySelector('#world');
for(let i=0;i<pack.levels.length;i+=4){const o=document.createElement('option');o.value=i;o.textContent=pack.levels[i].title+' · levels '+(i+1)+'–'+(i+4);select.append(o)}
const names=['Approach','Change of rhythm','Commitment','Precision'];
function draw(){document.querySelector('#cards').innerHTML=pack.levels.slice(+select.value,+select.value+4).map((c,i)=>{const l=c.level;let paths=l.platforms.map(p=>`<path d="${p.d}" fill="#03060b" stroke="${p.sourceShapeId==='wedge'?'#66ffd9':'#03060b'}" stroke-width="1.5"/>`).join('');paths+=(l.hazards||[]).map(p=>`<path d="${p.d}" fill="#03060b" stroke="#ff8547"/>`).join('');paths+=(l.blackHoles||[]).map(p=>`<circle cx="${p.x}" cy="${p.y}" r="${p.radius}" fill="black"/><circle cx="${p.x}" cy="${p.y}" r="${p.pullRadius}" fill="none" stroke="#bfa0ff"/>`).join('');paths+=l.stars.map(s=>{const p=Array.from({length:10},(_,j)=>{let a=-Math.PI/2+j*Math.PI/5,r=j%2?3:7;return `${s.x+Math.cos(a)*r},${s.y+Math.sin(a)*r}`}).join(' ');return `<polygon points="${p}" fill="#ffd166"/>`}).join('');return `<article class="card"><h2>level_${c.number} · ${names[i]}</h2><svg viewBox="0 0 390 1080">${paths}</svg><p>${c.routes.length} crossings · ${l.stars.length} stars</p></article>`}).join('')}
select.onchange=draw;draw();</script>'''.replace('PACK',json.dumps(pack,separators=(',',':')))
(root/'figma/layout-variety-review.html').write_text(page)
print('Exported all 84 playfields for visual comparison.')
